.progress-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 14px;
}
.progress-label {
  font-size: 0.85rem;
  color: var(--muted);
  white-space: nowrap;
}
.progress-track {
  flex: 1;
  height: 8px;
  background: var(--line);
  border-radius: 99px;
  overflow: hidden;
  max-width: 320px;
}
.progress-fill {
  height: 100%;
  background: var(--teal);
  border-radius: 99px;
  transition: width 0.4s ease;
}

/* ── System Status ── */
.system-status-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 12px;
  margin-bottom: 20px;
