class PromotionGateSpy:
    def __init__(self):
        self.calls = []

    def promote(self, entry, target_state, approver=None):
        self.calls.append((entry.copy(), target_state, approver))
        updated = entry.copy()
        if approver:
            updated["approver"] = approver
        updated["lifecycle_state"] = target_state.value
        return updated


